package com.bank.accounts.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

// The ENTITY — internal. It has fields we must NOT expose, like the DB id
// and an internal risk flag. We never return this directly from the API.
@Entity
@Table(name = "accounts")
public class Account {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long internalId;          // internal auto-increment — never exposed
    private String accountNumber;     // stable public identifier
    private String holderName;
    private BigDecimal balance;
    private boolean internalRiskFlag; // internal — never exposed

    public String getAccountNumber() { return accountNumber; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
}
