package com.bank.accounts.dto;

import com.bank.accounts.model.Account;
import java.math.BigDecimal;

// The DTO — the public contract. Exposes only safe fields and the STABLE
// public account number, never the internal DB id or risk flag.
public class AccountResponse {
    private final String accountNumber;
    private final String holderName;
    private final BigDecimal balance;

    public AccountResponse(Account a) {
        this.accountNumber = a.getAccountNumber();
        this.holderName = a.getHolderName();
        this.balance = a.getBalance();
    }
    public String getAccountNumber() { return accountNumber; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
}
