package com.bank.accounts.filter;

import jakarta.servlet.*;
import jakarta.servlet.http.*;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import java.io.IOException;
import java.util.concurrent.atomic.AtomicInteger;

// Adds the rate-limit headers clients need to self-throttle, and returns 429
// with Retry-After when the quota is exceeded.
@Component
@Order(1)
public class RateLimitFilter implements Filter {

    private static final int LIMIT = 1000;
    private final AtomicInteger used = new AtomicInteger(0);  // demo counter

    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {
        HttpServletResponse response = (HttpServletResponse) res;
        int remaining = LIMIT - used.incrementAndGet();
        long reset = (System.currentTimeMillis() / 1000) + 60;

        response.setHeader("X-RateLimit-Limit", String.valueOf(LIMIT));
        response.setHeader("X-RateLimit-Remaining", String.valueOf(Math.max(remaining, 0)));
        response.setHeader("X-RateLimit-Reset", String.valueOf(reset));

        if (remaining < 0) {
            response.setStatus(429);                         // Too Many Requests
            response.setHeader("Retry-After", "60");
            response.getWriter().write("{\"title\":\"Rate limit exceeded\",\"status\":429}");
            return;
        }
        chain.doFilter(req, res);
    }
}
