package com.bank.accounts.controller;

import com.bank.accounts.dto.AccountResponse;
import com.bank.accounts.exception.AccountNotFoundException;
import com.bank.accounts.model.Account;
import com.bank.accounts.repository.AccountRepository;
import org.springframework.data.domain.*;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;

// Well-designed: versioned path, noun resource, correct methods + status
// codes, pagination, DTOs (not entities), proper content type.
@RestController
@RequestMapping(value = "/api/v1/accounts", produces = MediaType.APPLICATION_JSON_VALUE)
public class AccountController {

    private final AccountRepository repo;

    public AccountController(AccountRepository repo) { this.repo = repo; }

    // GET a single resource by its STABLE public id; 404 if absent (not 200).
    @GetMapping("/{accountNumber}")
    public AccountResponse get(@PathVariable String accountNumber) {
        Account account = repo.findByAccountNumber(accountNumber)
                .orElseThrow(() -> new AccountNotFoundException(accountNumber));
        return new AccountResponse(account);   // DTO, never the entity
    }

    // GET a collection — ALWAYS paginated.
    @GetMapping
    public Page<AccountResponse> list(@RequestParam(defaultValue = "0") int page,
                                      @RequestParam(defaultValue = "20") int size) {
        return repo.findAll(PageRequest.of(page, Math.min(size, 100)))
                .map(AccountResponse::new);
    }

    // POST creates — returns 201 Created with a Location header, not 200.
    @PostMapping
    public ResponseEntity<AccountResponse> create(@RequestBody Account newAccount) {
        Account saved = repo.save(newAccount);
        return ResponseEntity
                .created(java.net.URI.create("/api/v1/accounts/" + saved.getAccountNumber()))
                .body(new AccountResponse(saved));
    }
}
