package com.bank.accounts.exception;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import java.util.Map;

// Honest errors: real status codes + a consistent Problem-Details-style body,
// never 200-for-everything.
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(AccountNotFoundException.class)
    public ResponseEntity<Map<String, Object>> notFound(AccountNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(Map.of(
                "type", "https://api.bank.com/errors/account-not-found",
                "title", "Account not found",
                "status", 404,
                "detail", "No account with number " + ex.getAccountNumber()));
    }
}
